mapper.select:
select

from ASSET_CONFIG_DETAIL
where ASSET_CONFIG_CODE = #{assetConfigCode,jdbcType=VARCHAR}
and ASSET_TYPE = #{assetType,jdbcType=VARCHAR}

mapper.delete:
delete from ASSET_CONFIG_DETAIL
where ASSET_CONFIG_CODE = #{assetConfigCode,jdbcType=VARCHAR}
  and ASSET_TYPE = #{assetType,jdbcType=VARCHAR}

mapper.update:
update ASSET_CONFIG_DETAIL
set TOTAL_RATIO = #{totalRatio,jdbcType=DECIMAL},
    TOTAL_AMT = #{totalAmt,jdbcType=DECIMAL},
    CUR_PER_AMT = #{curPerAmt,jdbcType=DECIMAL},
    REMARK = #{remark,jdbcType=VARCHAR},
    UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where ASSET_CONFIG_CODE = #{assetConfigCode,jdbcType=VARCHAR}
  and ASSET_TYPE = #{assetType,jdbcType=VARCHAR}
